      vocab: [['Reflection', 'The bouncing back of a wave at a boundary.'], ['Echo', 'A reflected sound heard after a measurable delay.'], ['Refraction', 'Change in direction of a wave due to a change in speed.'], ['Diffraction', 'Spreading of a wave through an opening or around an obstacle.'], ['Normal', 'Line perpendicular to a boundary, used to measure angles.'], ['Sonar', 'Locating objects by timing reflected sound pulses.']],
      formulas: [
        { eq: 'd = v·t / 2', id: 'echo', vars: [['d', 'distance to reflector', 'm'], ['v', 'wave speed', 'm/s'], ['t', 'round-trip time', 's']], when: 'Echo and sonar ranging.' },
        { eq: 'sin θ₁ / v₁ = sin θ₂ / v₂', id: 'wavesnell', vars: [['θ', 'angle from the normal', '°'], ['v', 'wave speed in each medium', 'm/s']], when: 'Refraction of any wave at a boundary.' },
      ],
      units: 'In d = vt/2, (m/s)(s) = m. In the refraction law, the ratio v₂/v₁ is unitless, so any consistent speed unit works.',
      example: {
        problem: 'A bat emits a 40 kHz ultrasonic chirp and hears the echo from a moth 0.012 s later. Find the distance to the moth and the wavelength of the chirp (v = 343 m/s).',
        steps: ['Round trip: d = vt/2 = 343 × 0.012/2 = 2.06 m.', 'Wavelength: λ = v/f = 343/40 000 = 0.0086 m = 8.6 mm.', 'An 8.6 mm wavelength is smaller than a moth, so the chirp reflects strongly instead of diffracting around it.'],
        answer: 'd ≈ 2.06 m; λ ≈ 8.6 mm',
      },
      guided: [
        { id: 'g1', kind: 'num', q: 'A shout echoes off a cliff and returns 0.80 s later (v = 343 m/s). How far away is the cliff?', answer: 137.2, unit: 'm', calc: '343 * 0.80 / 2', hints: ['Divide the round trip by 2.'], solution: 'd = 343 × 0.80/2 = 137 m.' },
        { id: 'g2', kind: 'num', q: 'A water wave (v = 2.0 m/s, λ = 0.50 m) enters shallow water where v = 1.2 m/s. New wavelength?', answer: 0.3, unit: 'm', calc: '1.2 / (2.0 / 0.50)', hints: ['Find f first; it does not change.'], solution: 'f = 2.0/0.50 = 4.0 Hz; λ = 1.2/4.0 = 0.30 m.' },
      ],
      practice: [
        { id: 'p1', kind: 'num', q: 'A 500 Hz sound passes from air into water (v = 1480 m/s). Wavelength in water?', answer: 2.96, unit: 'm', calc: '1480 / 500', solution: 'f stays 500 Hz: λ = 1480/500 = 2.96 m.' },
        { id: 'p2', kind: 'num', q: 'A ship’s sonar ping returns from the seabed 0.40 s after it is sent (v = 1530 m/s). Depth?', answer: 306, unit: 'm', calc: '1530 * 0.40 / 2', solution: 'd = 1530 × 0.40/2 = 306 m.' },
        { id: 'p3', kind: 'num', q: 'A water wave moving at 1.8 m/s hits a boundary at 30° from the normal and enters water where it moves at 1.2 m/s. Angle of refraction?', answer: 19.5, unit: '°', calc: 'Math.asin(1.2 / 1.8 * Math.sin(P.deg(30))) * 180 / Math.PI', solution: 'sin θ₂ = (1.2/1.8) sin30° = 0.333 → θ₂ = 19.5°, bent toward the normal.' },
        { id: 'p4', kind: 'mc', q: 'You hear but cannot see around a corner mainly because…', choices: ['sound is faster than light', 'sound wavelengths are comparable to doorways, so sound diffracts', 'light cannot reflect', 'air absorbs light'], correct: 1, solution: 'Diffraction is strong when λ is comparable to the opening; light’s λ is about a million times smaller.' },
        { id: 'p5', kind: 'mc', q: 'An upright pulse reflects from the fixed end of a rope. The reflected pulse is…', choices: ['upright', 'inverted', 'absent', 'twice as tall'], correct: 1, solution: 'The fixed end pulls back down on the rope, producing an inverted reflection.' },
      ],
      misconceptions: [
        { wrong: 'A wave’s frequency changes when it enters a new medium.', right: 'Frequency is fixed by the source; speed and wavelength change.', feedback: 'Your voice sounds the same pitch underwater, just muffled.' },
        { wrong: 'Echo distance is speed × time.', right: 'The echo time covers the trip there and back, so d = vt/2.', feedback: 'Draw the path out and back.' },
        { wrong: 'Diffraction only happens to sound, not light.', right: 'All waves diffract; light diffracts noticeably only through openings near its tiny wavelength.', feedback: 'See the fringes from a thin slit in Section 14.7.' },
      ],
      visual: { kind: 'refract', title: 'Water wave entering slower water (relative index n = v_ref/v, ratio 1.5)', n1: 1.0, n2: 1.5, theta: 30 },
      investigate: 'In the Wave Interference Lab, use the ripple-tank mode: send plane waves into a shallow region at an angle and measure the new direction, then pass them through slits of different widths to see when diffraction becomes strong.',
      mastery: ['I can use echo timing to find distances.', 'I can explain refraction with constant frequency and changing wavelength.', 'I can predict when diffraction is significant by comparing λ with the opening.'],
      honors: {
        prompt: 'Sound in air (343 m/s) strikes a calm lake surface (water: 1480 m/s). Beyond what angle of incidence will none of the sound enter the water? Explain why this differs from light, which bends toward the normal entering water.',
        solution: 'Sound speeds up entering water, so it bends away from the normal. sin θ_c = v_air/v_water = 343/1480 = 0.232 → θ_c = 13.4°. Beyond 13.4° the sound is totally reflected. Light slows down in water, so it bends toward the normal and has no such limit going in.',
        calc: ['Math.asin(343 / 1480) * 180 / Math.PI'], answers: [13.4],
      },
      explainKeys: ['frequency stays the same when a wave changes medium', 'echo distance is speed times time divided by two', 'diffraction is strong when the wavelength is comparable to the opening'],
      explainWords: [['frequency', 'same', 'wavelength'], ['echo', 'half', 'there and back'], ['diffraction', 'opening', 'comparable', 'spread']],
